import{loadCatalog,safeImage,whats}from'./api.js';
let content,revision,current,frame=0;const $=s=>document.querySelector(s),color=$('#color'),size=$('#size'),dialog=$('#dialog');
function options(select,values,label){const old=select.value;select.replaceChildren(new Option(label,''),...values.map(v=>new Option(v,v)));if(values.includes(old))select.value=old}
function paint(){const t=content.texts;document.querySelectorAll('[data-text]').forEach(el=>el.textContent=t[el.dataset.text]||'');$('#heroImage').src=safeImage(t.heroImage);document.querySelectorAll('[data-whatsapp]').forEach(a=>a.href=whats(t.whatsapp,'Olá! Vim pelo catálogo da Camila Borges e gostaria de mais informações.'));try{const u=new URL(t.maps);$('#mapsLink').href=u.protocol==='https:'?u.href:'#'}catch{$('#mapsLink').href='#'}options(color,[...new Set(content.models.flatMap(m=>m.colors.map(c=>c.name)))],'Todas as cores');options(size,[...new Set(content.models.flatMap(m=>m.sizes))],'Todos os tamanhos');render()}
function render(){const models=content.models.filter(m=>(!color.value||m.colors.some(c=>c.name===color.value))&&(!size.value||m.sizes.includes(size.value)));const grid=$('#grid');grid.replaceChildren();models.forEach(m=>{const b=document.createElement('button');b.className='card';const photo=document.createElement('div');photo.className='photo';const img=document.createElement('img');img.src=safeImage(m.photos[0]);img.alt='Vestido '+m.name;img.loading='lazy';photo.append(img);const h=document.createElement('h3');h.textContent=m.name+' ↗';const info=document.createElement('div');info.className='card-info';const colors=document.createElement('span');colors.textContent=m.colors.map(c=>c.name).join(' · ');const sizes=document.createElement('span');sizes.textContent=m.sizes.join(' · ');info.append(colors,sizes);b.append(photo,h,info);b.onclick=()=>open(m);grid.append(b)});if(!models.length){const p=document.createElement('p');p.className='empty';p.textContent='Nenhum modelo nesta combinação. Experimente outra cor ou tamanho.';grid.append(p)}$('#count').textContent=models.length+(models.length===1?' modelo':' modelos')}
function photo(){const photos=current.photos.filter(safeImage);frame=(frame+photos.length)%photos.length;$('#modalImg').src=safeImage(photos[frame]);$('#modalImg').alt='Vestido '+current.name;$('#page').textContent=`${frame+1}/${photos.length}`;$('#prev').disabled=$('#next').disabled=photos.length<2}
function open(m){current=m;frame=0;$('#modalTitle').textContent=m.name;$('#modalText').textContent=m.desc;$('#modalSizes').textContent='Cores: '+m.colors.map(c=>c.name).join(', ')+' · Tamanhos: '+m.sizes.join(', ');$('#modelWhatsApp').href=whats(content.texts.whatsapp,'Olá! Vim pelo catálogo da Camila Borges e gostaria de saber mais sobre o vestido '+m.name+'.');photo();dialog.showModal()}
$('#prev').onclick=()=>{frame--;photo()};$('#next').onclick=()=>{frame++;photo()};color.onchange=size.onchange=render;$('#reset').onclick=()=>{color.value=size.value='';render()};
async function sync(){try{const row=await loadCatalog();if(row.revision!==revision){content=row.content;revision=row.revision;paint()}}catch(e){if(!content){$('#grid').textContent='Não foi possível carregar os vestidos. Atualize a página para tentar novamente.'}}}await sync();setInterval(()=>{if(!document.hidden)sync()},10000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sync()});
